import AVFoundation
import UIKit

/// Plays the game's short sound effects (SFX) with no audible latency.
///
/// Where each sound comes from, first match wins:
/// 1. a file in the app bundle: `pickup.wav` (or .mp3 / .caf / .m4a), `snap.wav`, `snap_keys.wav`, `lights_on.wav`, …
///    The bundled files live in `TidyDesk/Resources/Sounds/` (generated by `tools/generate_sounds.py`;
///    replace them with your own recordings anytime; same names, no code change);
/// 2. a Data Set with the same name in `Assets.xcassets` (`NSDataAsset`);
/// 3. a sound synthesized in memory by `ToneSynth`, so the game never goes silent because a file is missing.
///
/// Latency: every sound is decoded and `prepareToPlay()`-ed once in `preload()` (called at app launch),
/// and each sound has a few pre-warmed "voices" so rapid snaps overlap instead of cutting each other off.
@MainActor
final class SoundManager {
    static let shared = SoundManager()

    enum Sound: String, CaseIterable {
        /// Lifting an item from the drawer or the desk.
        case pickup
        /// Item clicks into the desk grid.
        case snap
        /// Invalid drop (overlap / over the edge): item springs back.
        case error
        /// Whole desk set up.
        case complete
        /// Item put back into the drawer.
        case drop
        /// Tap-to-rotate.
        case rotate
        /// Material snaps (see `ItemMaterial`); `.snap` is the hard-device one.
        case snapKeys = "snap_keys"
        case snapCeramic = "snap_ceramic"
        case snapSoft = "snap_soft"
        case snapCable = "snap_cable"
        /// Soft blip when a lamp / screen / speaker / keyboard switches on after landing.
        case powerOn = "power_on"
        /// Level clear, the "after" moment: a warm swell as the desk lights up (before the `complete` chime).
        case lightsOn = "lights_on"

        static func snap(for material: ItemMaterial) -> Sound {
            switch material {
            case .keys: .snapKeys
            case .ceramic: .snapCeramic
            case .soft: .snapSoft
            case .cable: .snapCable
            case .device: .snap
            }
        }

        /// Mixing levels: the snap is the hero sound, the error stays gentle.
        var volume: Float {
            switch self {
            case .pickup: 0.45
            case .snap: 0.9
            case .error: 0.5
            case .complete: 0.75
            case .drop: 0.6
            case .rotate: 0.45
            case .snapKeys: 0.85
            case .snapCeramic: 0.7
            case .snapSoft: 0.95
            case .snapCable: 0.8
            case .powerOn: 0.35
            case .lightsOn: 0.55
            }
        }

        /// Simultaneous voices kept ready.
        var voices: Int {
            switch self {
            case .complete, .lightsOn: 1
            default: 3
            }
        }
    }

    enum Source: Equatable {
        case bundleFile(String)
        case assetCatalog
        case synthesized
    }

    /// Where each sound was loaded from (handy when checking that real audio files are picked up).
    private(set) var sources: [Sound: Source] = [:]
    private var players: [Sound: [AVAudioPlayer]] = [:]
    private var cursor: [Sound: Int] = [:]
    private let defaults: UserDefaults
    private let bundle: Bundle

    init(defaults: UserDefaults = .standard, bundle: Bundle = .main) {
        self.defaults = defaults
        self.bundle = bundle
        defaults.register(defaults: [SettingsKeys.soundEnabled: true])
    }

    var isEnabled: Bool { defaults.bool(forKey: SettingsKeys.soundEnabled) }
    var isPreloaded: Bool { !players.isEmpty }

    /// Decodes every sound and warms up the audio hardware. Safe to call more than once.
    func preload() {
        guard !isPreloaded else { return }
        // .ambient: mixes with the player's own music and respects the silent switch,
        // which is what players expect from a cozy puzzle game.
        let session = AVAudioSession.sharedInstance()
        try? session.setCategory(.ambient, mode: .default, options: [.mixWithOthers])
        try? session.setActive(true)

        for sound in Sound.allCases {
            let (data, source) = Self.loadData(for: sound, in: bundle)
            sources[sound] = source
            players[sound] = (0..<sound.voices).compactMap { _ in
                guard let player = try? AVAudioPlayer(data: data) else { return nil }
                player.volume = sound.volume
                player.prepareToPlay()
                return player
            }
        }
    }

    func play(sound: Sound) {
        guard isEnabled else { return }
        if !isPreloaded { preload() }
        guard let pool = players[sound], !pool.isEmpty else { return }
        // Prefer an idle voice; otherwise restart the oldest one.
        let start = cursor[sound, default: 0]
        let index = (0..<pool.count).map { (start + $0) % pool.count }.first { !pool[$0].isPlaying } ?? start % pool.count
        cursor[sound] = index + 1
        let player = pool[index]
        player.currentTime = 0
        player.play()
    }

    // MARK: Loading

    static func loadData(for sound: Sound, in bundle: Bundle) -> (Data, Source) {
        for ext in ["wav", "mp3", "caf", "m4a"] {
            if let url = bundle.url(forResource: sound.rawValue, withExtension: ext)
                ?? bundle.url(forResource: sound.rawValue, withExtension: ext, subdirectory: "Sounds"),
               let data = try? Data(contentsOf: url) {
                return (data, .bundleFile("\(sound.rawValue).\(ext)"))
            }
        }
        if let asset = NSDataAsset(name: sound.rawValue, bundle: bundle) {
            return (asset.data, .assetCatalog)
        }
        return (ToneSynth.wav(for: sound), .synthesized)
    }
}
